const fs = require\('fs'\);
const zlib = require\('zlib'\);

function crc32\(buf\) {
  let crc = 0xFFFFFFFF;
  for \(let i = 0; i < buf.length; i++\) {
    crc ^= buf[i];
    for \(let j = 0; j < 8; j++\) {
      crc = \(crc >>> 1\) ^ \(crc & 1 ? 0xEDB88320 : 0\);
    }
  }
  return \(crc ^ 0xFFFFFFFF\) >>> 0;
}

function makeChunk\(type, data\) {
  const length = Buffer.alloc\(4\);
  length.writeUInt32BE\(data.length, 0\);
  const typeBuffer = Buffer.from\(type\);
  const crcData = Buffer.concat\([typeBuffer, data]\);
  const crc = Buffer.alloc\(4\);
  crc.writeUInt32BE\(crc32\(crcData\), 0\);
  return Buffer.concat\([length, typeBuffer, data, crc]\);
}

function createPNG\(size\) {
  const signature = Buffer.from\([137, 80, 78, 71, 13, 10, 26, 10]\);
  const ihdrData = Buffer.alloc\(13\);
  ihdrData.writeUInt32BE\(size, 0\);
  ihdrData.writeUInt32BE\(size, 4\);
  ihdrData[8] = 8; ihdrData[9] = 2;
  const ihdr = makeChunk\('IHDR', ihdrData\);
  const rawData = Buffer.alloc\(size * \(1 + size * 3\)\);
  for \(let y = 0; y < size; y++\) {
    rawData[y * \(1 + size * 3\)] = 0;
    for \(let x = 0; x < size; x++\) {
      const offset = y * \(1 + size * 3\) + 1 + x * 3;
      rawData[offset] = 249; rawData[offset+1] = 115; rawData[offset+2] = 22;
    }
  }
  const compressed = zlib.deflateSync\(rawData\);
  const idat = makeChunk\('IDAT', compressed\);
  const iend = makeChunk\('IEND', Buffer.alloc\(0\)\);
  return Buffer.concat\([signature, ihdr, idat, iend]\);
}

fs.writeFileSync\('public/icons/icon-192.png', createPNG\(192\)\);
fs.writeFileSync\('public/icons/icon-512.png', createPNG\(512\)\);
fs.writeFileSync\('public/icons/icon-maskable-512.png', createPNG\(512\)\);
console.log\('Created placeholder icons'\);
")

